def permanent(matrix):
    import itertools
    n = len(matrix)
    total_permanent = 0
    indices = list(range(n))

    for p in itertools.permutations(indices):
        product = 1
        for i in range(n):
            product *= matrix[i][p[i]]
        total_permanent += product
    return total_permanent

# Candidate A uses N=16, but we test N=4 for feasibility
N = 4
A_matrix = [[0] * N for _ in range(N)]

# A_ij = 1 if j - i mod N is in {0, 1, 2, 3}
# For N=4, j-i mod 4 is always in {0, 1, 2, 3}. So A is the all-ones matrix J_4.
for i in range(N):
    for j in range(N):
        if (j - i) % N in {0, 1, 2, 3}:
            A_matrix[i][j] = 1

perm_A = permanent(A_matrix)
print(f"N=4, Permanent(A): {perm_A}")

